import {gradeLabel} from '../domain/selection.mjs?v=r65';
import {phaseVisual} from '../lesson-visuals.mjs?v=r65';
import {resourceKindsFor,resourcePageInfo,resourceOutput,readerHistoryAction} from '../ux.mjs?v=r65';

export function createReader({$,t,e,options,curriculum,repository,getCurrentLesson,notify,stage,cropMarkup,visualAlt,visualCaption}){
let readerState;
const resources=()=>repository.load();
function bookName(kind){return kind==='guide'?t('संदर्शिका','Guide'):kind==='workbook'?t('कार्यपुस्तिका','Workbook'):t('पाठ्यपुस्तक','Textbook');}
function bookButtons(l){return `<button class="button" data-resource="guide" data-grade="${l.grade}" data-page="${l.source.pdfPage-1}">${t('संदर्शिका पृष्ठ','Guide page')} ${l.source.page}</button>${resourceKindsFor(repository.peek(),l.grade).map(kind=>`<button class="button" data-resource="${kind}" data-grade="${l.grade}">${t('पूरी','Whole')} ${bookName(kind)}</button>`).join('')}<button class="button" data-print>${t('संदर्शिका का पृष्ठ छापें','Print guide page')}</button><p class="small">${t('पाठ्यपुस्तक का संदर्भ ऊपर दिया है। जो पुस्तक ऐप में नहीं है, उसे मुद्रित पुस्तक में देखें।','Textbook references are above. Use your printed copy for books not supplied in this app.')}</p>`;}
function readerPageLabel(r,index=r.page){const info=resourcePageInfo(repository.peek(),r.kind,r.grade,r.pages[index],index);if(r.visual?.page!=null)info.printed=r.visual.page;else if(r.lesson?.source.image===r.pages[index])info.printed=r.lesson.source.page;return info.printed!=null?t('पृष्ठ ','Page ')+info.printed:t('आरंभिक / अन्य पृष्ठ','Front matter / other page')+' · '+t('PDF क्रमांक ','PDF index ')+info.pdf;}
function readerActions(){return `<div class="reader-actions"><button class="button" data-print-preview>${t('इस पृष्ठ का प्रिंट देखें','Preview page for printing')}</button><button class="button" data-download-page>${t('इस पृष्ठ की फ़ाइल डाउनलोड करें','Download this page as a file')}</button><span class="small" id="reader-action-status" role="status"></span></div>`;}
function printDocument(image,label){$('#print-root').innerHTML=`<h1>${e(label)}</h1><img src="${e(image)}" alt="${e(label)}">`;$('#print-root').dataset.resource=image;}
function previewPrint(){const l=getCurrentLesson(),output=resourceOutput($('#reader').open?readerState:null,l);if(!$('#reader').open){openReader('guide',l.grade,l.source.pdfPage-1);return;}const r=readerState;printDocument(output.image,bookName(output.kind)+' · '+readerPageLabel(r));$('#reader-body').innerHTML=`<h3>${t('छपने वाला पूरा पृष्ठ','Full page to be printed')}</h3><p>${bookName(output.kind)} · ${readerPageLabel(r)}</p><img class="print-preview" src="${e(output.image)}" alt="${readerPageLabel(r)}"><div class="reader-actions"><button class="button primary" data-confirm-print>${t('अब छापें','Print now')}</button><button class="button" data-cancel-print>${t('पृष्ठ पर लौटें','Return to page')}</button></div>`;}
async function downloadPage(){const r=readerState,status=$('#reader-action-status');try{status.textContent=t('फ़ाइल तैयार हो रही है…','Preparing file…');const response=await fetch(r.pages[r.page]);if(!response.ok)throw Error();const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=r.pages[r.page].split('/').pop();link.click();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent=t('फ़ाइल डाउनलोड के लिए भेजी गई।','File sent to your browser downloads.');}catch{status.textContent=t('फ़ाइल नहीं खुली। फिर प्रयास करें।','File unavailable. Please retry.');}}
async function openReader(kind,grade,page=0,images){try{const data=await resources();const pages=images||data[kind]?.[grade]?.pages;if(!pages?.length){notify(t('यह पुस्तक इस संग्रह में उपलब्ध नहीं है। मुद्रित पुस्तक देखें।','This book was not supplied. Use the printed book.'));return;}readerState={kind,grade,pages,page:Math.max(0,Math.min(page,pages.length-1)),zoom:100,returnFocus:document.activeElement};showReader();renderReader();}catch{notify(t('पृष्ठ नहीं खुल पाया। इंटरनेट जाँचकर फिर प्रयास करें।','Page could not load. Check your connection and retry.'));}}
function openVisual(n){
 const l=getCurrentLesson(),p=l?.phases[n];if(!p)return;
 const visual=phaseVisual(l,p,curriculum.visualStyle);if(!visual)return;
 readerState={kind:visual.kind==='worksheet'?'workbook':'guide',grade:l.grade,pages:[visual.image],page:0,zoom:100,visual,lesson:l,phase:p,returnFocus:document.activeElement};
 showReader();renderReader();
}
function bindReaderImage(){const im=$('#reader-img');im.onload=()=>{if(im.parentElement.classList.contains('full-page'))im.parentElement.style.aspectRatio=im.naturalWidth/im.naturalHeight;$('.reader-loading').hidden=true;};im.onerror=()=>{$('.reader-loading').hidden=true;$('.reader-error').hidden=false;};if(im.complete&&im.naturalWidth)im.onload();}
function renderVisualReader(){const r=readerState;
 $('#reader-title').textContent=visualCaption(r.visual)+' · '+(r.visual.page!=null?t('पृष्ठ ','Page ')+r.visual.page:stage(r.phase));
 $('#reader-body').innerHTML=`<div class="zoom-controls"><button class="button" data-zoom="-25" ${r.zoom===100?'disabled':''} aria-label="${t('चित्र छोटा करें','Zoom out')}">−</button><span>${r.zoom}%</span><button class="button" data-zoom="25" aria-label="${t('चित्र बड़ा करें','Zoom in')}">+</button><button class="text-button" data-reader-reset>${t('पूरा चित्र','Fit image')}</button></div><p class="reader-loading" role="status">${t('चित्र खोल रहे हैं…','Loading illustration…')}</p><div class="visual-reader-scroll"><div class="visual-reader-art" style="width:${r.zoom}%">${cropMarkup(r.visual,visualAlt(r.lesson,r.phase,r.visual),'reader-img')}</div></div><div class="reader-error" hidden><p>${t('चित्र नहीं खुल पाया। इंटरनेट जाँचें।','Image could not load. Check your connection.')}</p><button class="button" data-reader-retry>${t('फिर प्रयास करें','Retry')}</button></div>${readerActions()}<p class="visual-provenance">${visualCaption(r.visual)} · ${t('मूल पुस्तक से','From the original book')}<br>${e(r.lesson.source.notice||'')}</p><button class="button" data-open-source-page>${t('संदर्भ के लिए पूरा मूल पृष्ठ खोलें','Open the full original page for context')}</button>`;
 bindReaderImage();
}
function renderReader(){const r=readerState;if(!r)return;if(r.visual){renderVisualReader();return;}$('#reader-title').textContent=t(r.kind==='guide'?'मूल संदर्शिका':r.kind==='workbook'?'कार्यपुस्तिका':'पाठ्यपुस्तक',r.kind==='guide'?'Original guide':r.kind==='workbook'?'Workbook':'Textbook')+' · '+gradeLabel(curriculum,r.grade,$('html')?.lang||'hi');$('#reader-body').innerHTML=`<div class="reader-controls"><button class="button" data-reader-prev aria-label="${t('पिछला पृष्ठ','Previous page')}" ${r.page===0?'disabled':''}>←</button><label>${t('पृष्ठ चुनें','Choose page')}<select id="reader-page">${options(r.pages.map((p,i)=>[i,readerPageLabel(r,i)]),r.page)}</select></label><button class="button" data-reader-next aria-label="${t('अगला पृष्ठ','Next page')}" ${r.page===r.pages.length-1?'disabled':''}>→</button></div><div class="reader-jump"><label for="printed-page">${t('किताब पर छपा पृष्ठ नंबर','Printed page number')}</label><input id="printed-page" type="text" inputmode="numeric" size="5"><button class="button" data-reader-jump>${t('पृष्ठ खोलें','Go to page')}</button><span role="status" id="page-jump-status"></span></div><div class="zoom-controls"><button class="button" data-zoom="-25" ${r.zoom===100?'disabled':''} aria-label="${t('चित्र छोटा करें','Zoom out')}">−</button><span>${r.zoom}%</span><button class="button" data-zoom="25" aria-label="${t('चित्र बड़ा करें','Zoom in')}">+</button><button class="text-button" data-reader-reset>${t('पूरा पृष्ठ','Fit page')}</button></div>${readerActions()}<p class="reader-loading" role="status">${t('पृष्ठ खोल रहे हैं…','Loading page…')}</p><div class="reader-image"><img id="reader-img" style="width:${r.zoom}%" src="${e(r.pages[r.page])}" alt="${bookName(r.kind)} · ${e(readerPageLabel(r))}"></div><div class="reader-error" hidden><p>${t('चित्र नहीं खुल पाया। इंटरनेट जाँचें।','Image could not load. Check your connection.')}</p><button class="button" data-reader-retry>${t('फिर प्रयास करें','Retry')}</button></div>`;const im=$('#reader-img');im.onload=()=>$('.reader-loading').hidden=true;im.onerror=()=>{$('.reader-loading').hidden=true;$('.reader-error').hidden=false;};if(im.complete&&im.naturalWidth)im.onload();}
let readerToken=0;
function showReader(){readerState.historyToken=++readerToken;history.pushState({reader:readerToken},'',location.href);$('#reader').showModal();}
function closeReader(){if(readerState&&history.state?.reader===readerState.historyToken)history.back();else if($('#reader').open)$('#reader').close();}
window.addEventListener('popstate',()=>{const action=readerHistoryAction(history.state,readerState,$('#reader').open);if(action==='open'){$('#reader').showModal();renderReader();}else if(action==='close')$('#reader').close();});
$('#reader').addEventListener('cancel',ev=>{ev.preventDefault();closeReader();});
$('#reader-close').onclick=closeReader;$('#reader').addEventListener('close',()=>readerState?.returnFocus?.isConnected&&readerState.returnFocus.focus({preventScroll:true}));
$('#reader').addEventListener('click',async ev=>{const b=ev.target.closest('button');if(!b||!readerState)return;const r=readerState;if(b.hasAttribute('data-open-source-page')){try{const data=await resources(),image=r.pages[r.page],pages=data[r.kind]?.[r.grade]?.pages||r.pages;r.pages=pages;r.page=Math.max(0,pages.indexOf(image));r.visual=null;r.zoom=100;renderReader();}catch{notify(t('मूल पृष्ठ नहीं खुला। फिर प्रयास करें।','Original page unavailable. Retry.'));}return;}if(b.hasAttribute('data-reader-jump')){const wanted=$('#printed-page').value.replace(/[०-९]/g,c=>String('०१२३४५६७८९'.indexOf(c))).trim(),index=r.pages.findIndex((image,i)=>resourcePageInfo(repository.peek(),r.kind,r.grade,image,i).printed!=null&&/^\d+$/.test(wanted)&&String(resourcePageInfo(repository.peek(),r.kind,r.grade,image,i).printed)===String(Number(wanted)));if(index>=0){r.page=index;renderReader();}else $('#page-jump-status').textContent=t('इस नंबर का सत्यापित पृष्ठ नहीं मिला। ऊपर पृष्ठ सूची से चुनें।','No verified page with this number. Choose from the page list above.');return;}if(b.hasAttribute('data-print-preview')){previewPrint();return;}if(b.hasAttribute('data-download-page')){downloadPage();return;}if(b.hasAttribute('data-cancel-print')){renderReader();return;}if(b.hasAttribute('data-confirm-print')){try{await $('#print-root img').decode();window.print();}catch{notify(t('पृष्ठ तैयार नहीं हुआ। फिर प्रयास करें।','Page not ready. Retry.'));}return;}if(b.hasAttribute('data-reader-prev'))r.page--;else if(b.hasAttribute('data-reader-next'))r.page++;else if(b.dataset.zoom)r.zoom=Math.min(250,Math.max(100,r.zoom+Number(b.dataset.zoom)));else if(b.hasAttribute('data-reader-reset'))r.zoom=100;else if(!b.hasAttribute('data-reader-retry'))return;renderReader();});$('#reader').addEventListener('change',ev=>{if(ev.target.id==='reader-page'){readerState.page=Number(ev.target.value);renderReader();}});
window.addEventListener('beforeprint',()=>{if($('#reader').open&&readerState){const output=resourceOutput(readerState);printDocument(output.image,bookName(output.kind)+' · '+readerPageLabel(readerState));}});
return {bookButtons,openReader,openVisual,previewPrint};
}
